import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        int m = n * (n - 1) / 2;
        int size = n * (n - 1) + 1;

        int[][] dp = new int[n + 1][size];
        int[][] dp1 = new int[n + 1][size];

        dp[1][m] = 1;

        for (int i = 2; i <= n; i++) {
            int offset = (i - 1) * (i - 2) / 2;
            for (int x = m - offset; x <= m + offset; x++) {
                for (int d = -i + 1; d < i; d++) {
                    int x_d = x + d;
                    if (x_d >= 0 && x_d < size) {
                        dp[i][x_d] = (dp[i][x_d] + (int) ((long) dp[i - 1][x] * (i - Math.abs(d)) % mod)) % mod;
                    }
                }
            }
        }

        for (int i = 2; i <= n; i++) {
            int offset = (i - 1) * (i - 2) / 2;
            for (int x = m - offset; x <= m + offset; x++) {
                dp1[i][x] = (int) ((long) dp1[i - 1][x] * i % mod);
            }
            for (int x = m - offset; x <= m + offset; x++) {
                for (int d = 1; d < i; d++) {
                    int x_d = x - d;
                    if (x_d >= 0 && x_d < size) {
                        dp1[i][x_d] = (dp1[i][x_d] + (int) ((long) dp[i - 1][x] * (i - d) % mod)) % mod;
                    }
                }
            }
        }

        long result = 0;
        for (int x = m + 1; x < size; x++) {
            result = (result + dp1[n][x]) % mod;
        }

        System.out.println(result);
        scanner.close();
    }
}
